public class Solution {
    public static int solve(int n) {
        return count(n, 0, 0);
    }

    private static int count(int n, int open, int close) {
        if (open == n && close == n) return 1;
        int result = 0;
        if (open < n) result += count(n, open + 1, close);
        if (close < open) result += count(n, open, close + 1);
        return result;
    }
}

