public class Solution {
    public static int solve(int n) {
        return place(0, n, new boolean[n], new boolean[2 * n], new boolean[2 * n]);
    }

    private static int place(int row, int n, boolean[] columns, boolean[] down, boolean[] up) {
        if (row == n) return 1;
        int count = 0;
        for (int column = 0; column < n; column++) {
            int downIndex = row - column + n;
            int upIndex = row + column;
            if (columns[column] || down[downIndex] || up[upIndex]) continue;
            columns[column] = down[downIndex] = up[upIndex] = true;
            count += place(row + 1, n, columns, down, up);
            columns[column] = down[downIndex] = up[upIndex] = false;
        }
        return count;
    }
}

