import java.util.ArrayDeque;

public class Solution {
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static int solve(char[][] grid) {
        if (grid.length == 0) return 0;
        int columns = grid[0].length;
        boolean[][] visited = new boolean[grid.length][columns];
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        int islands = 0;
        for (int row = 0; row < grid.length; row++) {
            for (int column = 0; column < columns; column++) {
                if (grid[row][column] != '1' || visited[row][column]) continue;
                islands++;
                visited[row][column] = true;
                queue.addLast(row * columns + column);
                while (!queue.isEmpty()) {
                    int current = queue.removeFirst();
                    int currentRow = current / columns;
                    int currentColumn = current % columns;
                    for (int direction = 0; direction < 4; direction++) {
                        int nextRow = currentRow + DR[direction];
                        int nextColumn = currentColumn + DC[direction];
                        if (nextRow < 0 || nextRow >= grid.length || nextColumn < 0 || nextColumn >= columns) continue;
                        if (grid[nextRow][nextColumn] != '1' || visited[nextRow][nextColumn]) continue;
                        visited[nextRow][nextColumn] = true;
                        queue.addLast(nextRow * columns + nextColumn);
                    }
                }
            }
        }
        return islands;
    }
}

