public class Solution {
    public static int solve(int[][] meetings) {
        Arrays.sort(meetings, Comparator.<int[]>comparingInt(meeting -> meeting[1])
                .thenComparingInt(meeting -> meeting[0]));
        int count = 0;
        int lastEnd = Integer.MIN_VALUE;
        for (int[] meeting : meetings) {
