public class Solution {
    public static long solve(int[] cards) {
        PriorityQueue<Long> queue = new PriorityQueue<>();
        for (int card : cards) queue.add((long) card);
        long cost = 0;
        while (queue.size() > 1) {
            long merged = queue.remove() + queue.remove();
            cost += merged;
            queue.add(merged);
        }
        return cost;
    }
}

