import java.util.*;

public class Solution {
    public static int solve(String start, String target, String[] states) {
        if (start.equals(target)) return 0;
        Set<String> remaining = new LinkedHashSet<>(Arrays.asList(states));
        if (!remaining.contains(target)) return -1;
        remaining.remove(start);
        Queue<String> queue = new ArrayDeque<>();
        Map<String, Integer> distance = new HashMap<>();
        queue.add(start);
        distance.put(start, 0);
        while (!queue.isEmpty()) {
            String current = queue.remove();
            int nextDistance = distance.get(current) + 1;
            for (Iterator<String> iterator = remaining.iterator(); iterator.hasNext();) {
                String next = iterator.next();
                if (!oneCharacterApart(current, next)) continue;
                if (next.equals(target)) return nextDistance;
                iterator.remove();
                distance.put(next, nextDistance);
                queue.add(next);
            }
        }
        return -1;
    }

    private static boolean oneCharacterApart(String left, String right) {
        int differences = 0;
        for (int index = 0; index < left.length(); index++) {
            if (left.charAt(index) != right.charAt(index) && ++differences > 1) return false;
        }
        return differences == 1;
    }
}

