public class Solution {
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static int solve(int[][] grid, int startRow, int startColumn, int endRow, int endColumn) {
        int rows = grid.length;
        int columns = grid[0].length;
        int[][] distance = new int[rows][columns];
        for (int[] row : distance) Arrays.fill(row, -1);
        Queue<Integer> queue = new ArrayDeque<>();
        distance[startRow][startColumn] = 0;
        queue.add(startRow * columns + startColumn);
        while (!queue.isEmpty()) {
            int current = queue.remove();
            int row = current / columns;
            int column = current % columns;
            if (row == endRow && column == endColumn) return distance[row][column];
            for (int direction = 0; direction < 4; direction++) {
                int nextRow = row + DR[direction];
                int nextColumn = column + DC[direction];
                if (nextRow < 0 || nextRow >= rows || nextColumn < 0 || nextColumn >= columns) continue;
                if (grid[nextRow][nextColumn] == 1 || distance[nextRow][nextColumn] != -1) continue;
                distance[nextRow][nextColumn] = distance[row][column] + 1;
                queue.add(nextRow * columns + nextColumn);
            }
        }
        return -1;
    }
}

