public class Solution {
    public static int[] solve(int n, int[][] edges, int start) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int vertex = 0; vertex < n; vertex++) graph.add(new ArrayList<>());
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }
        int[] distance = new int[n];
        Arrays.fill(distance, -1);
        Queue<Integer> queue = new ArrayDeque<>();
        distance[start] = 0;
        queue.add(start);
        while (!queue.isEmpty()) {
            int current = queue.remove();
            for (int next : graph.get(current)) {
                if (distance[next] != -1) continue;
                distance[next] = distance[current] + 1;
                queue.add(next);
            }
        }
        int maximumDistance = 0;
        int count = 0;
        int smallestVertex = start;
        for (int vertex = 0; vertex < n; vertex++) {
            if (distance[vertex] < 0) continue;
            if (distance[vertex] > maximumDistance) {
                maximumDistance = distance[vertex];
                count = 1;
                smallestVertex = vertex;
            } else if (distance[vertex] == maximumDistance) {
                count++;
                smallestVertex = Math.min(smallestVertex, vertex);
            }
        }
        return new int[]{maximumDistance, count, smallestVertex};
    }
}

