import java.util.*;

public class Solution {
    public static int solve(int n, int[][] relations) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int work = 0; work < n; work++) graph.add(new ArrayList<>());
        for (int[] relation : relations) graph.get(relation[0]).add(relation[1]);
        boolean[][] reachable = new boolean[n][n];
        for (int start = 0; start < n; start++) {
            boolean[] visited = new boolean[n];
            Deque<Integer> stack = new ArrayDeque<>();
            visited[start] = true;
            stack.push(start);
            while (!stack.isEmpty()) {
                int current = stack.pop();
                for (int next : graph.get(current)) {
                    if (visited[next]) continue;
                    visited[next] = true;
                    reachable[start][next] = true;
                    stack.push(next);
                }
            }
        }
        int determined = 0;
        for (int current = 0; current < n; current++) {
            boolean knownWithAll = true;
            for (int other = 0; other < n; other++) {
                if (current == other) continue;
                if (reachable[current][other] == reachable[other][current]) {
                    knownWithAll = false;
                    break;
                }
            }
            if (knownWithAll) determined++;
        }
        return determined;
    }
}
